/**
 * Parity test: the TypeScript fitting port must reproduce the Python engine's anchors and
 * placement matrices on recorded landmarks (ai/tests/fixtures/*.landmarks.json). The
 * expectations file is generated by scripts/export_fitting_fixtures.py.
 */
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import type { JewelleryType } from "@/lib/api/types";
import { anchorsFor } from "./anchors";
import { AnchorError } from "./types";
import { fitAsset } from "./fitters";
import { isStrand, strandPlacement } from "./strand";
import type { Adjustments, AssetGeometry, Landmarks } from "./types";

const FIXTURES = join(__dirname, "../../../../../ai/tests/fixtures");

interface RawLandmarks {
  image_width: number;
  image_height: number;
  face: [number, number][] | null;
  face_score?: number;
  hands: { handedness: string; score: number; points: [number, number][] }[];
  pose: [number, number][] | null;
  pose_visibility: number[] | null;
}

interface ExpectedAsset {
  width: number;
  height: number;
  anchors: Record<string, [number, number]>;
  jewellery_type: JewelleryType;
  real_width_mm: number | null;
  real_height_mm: number | null;
}

interface ExpectedCase {
  asset: string;
  slot: string | null;
  error?: string;
  placements?: {
    anchors: {
      region: string;
      points: Record<string, [number, number]>;
      px_per_mm: number;
      rotation_deg: number;
      confidence: number;
      mirror: boolean;
    };
    fits: { adjustments: Adjustments; matrix: number[][]; bbox: number[] }[];
    strands: {
      adjustments: Adjustments;
      length_mm: number | null;
      bbox: number[];
      strips: { x0: number; x1: number; matrix: number[][] }[];
    }[] | null;
  }[];
}

interface Expectations {
  assets: Record<string, ExpectedAsset>;
  fixtures: Record<string, ExpectedCase[]>;
}

export function landmarksFromJson(raw: RawLandmarks): Landmarks {
  return {
    image_width: raw.image_width,
    image_height: raw.image_height,
    face: raw.face ? raw.face.map(([x, y]) => ({ x, y })) : null,
    face_score: raw.face_score,
    hands: raw.hands.map((h) => ({
      handedness: h.handedness,
      score: h.score,
      points: h.points.map(([x, y]) => ({ x, y })),
    })),
    pose: raw.pose ? raw.pose.map(([x, y]) => ({ x, y })) : null,
    pose_visibility: raw.pose_visibility,
  };
}

function geometry(key: string, asset: ExpectedAsset): AssetGeometry {
  return {
    width: asset.width,
    height: asset.height,
    anchors: Object.fromEntries(Object.entries(asset.anchors).map(([k, [x, y]]) => [k, { x, y }])),
    jewellery_type: asset.jewellery_type,
    real_width_mm: asset.real_width_mm,
    real_height_mm: asset.real_height_mm,
    asset_id: key,
  };
}

const expectations = JSON.parse(
  readFileSync(join(FIXTURES, "fitting_expectations.json"), "utf8"),
) as Expectations;
const fixtureNames = readdirSync(FIXTURES)
  .filter((f) => f.endsWith(".landmarks.json"))
  .map((f) => f.replace(".landmarks.json", ""));

describe("fitting parity with the Python engine", () => {
  it("covers every recorded fixture", () => {
    expect(Object.keys(expectations.fixtures).sort()).toEqual(fixtureNames.sort());
  });

  for (const name of fixtureNames) {
    const cases = expectations.fixtures[name] ?? [];
    const lm = landmarksFromJson(
      JSON.parse(readFileSync(join(FIXTURES, `${name}.landmarks.json`), "utf8")) as RawLandmarks,
    );
    for (const c of cases) {
      it(`${name}: ${c.asset}${c.slot ? ` (${c.slot})` : ""}`, () => {
        const asset = geometry(c.asset, expectations.assets[c.asset]!);
        if (c.error) {
          expect(() => anchorsFor(lm, asset.jewellery_type, c.slot)).toThrowError(AnchorError);
          try {
            anchorsFor(lm, asset.jewellery_type, c.slot);
          } catch (e) {
            expect((e as AnchorError).code).toBe(c.error);
          }
          return;
        }
        const sets = anchorsFor(lm, asset.jewellery_type, c.slot);
        expect(sets).toHaveLength(c.placements!.length);
        sets.forEach((anchors, i) => {
          const exp = c.placements![i]!;
          expect(anchors.region).toBe(exp.anchors.region);
          expect(anchors.mirror).toBe(exp.anchors.mirror);
          expect(anchors.px_per_mm).toBeCloseTo(exp.anchors.px_per_mm, 9);
          expect(anchors.rotation_deg).toBeCloseTo(exp.anchors.rotation_deg, 9);
          expect(anchors.confidence).toBeCloseTo(exp.anchors.confidence, 9);
          for (const [key, [x, y]] of Object.entries(exp.anchors.points)) {
            expect(Math.abs(anchors.points[key]!.x - x)).toBeLessThan(1e-6);
            expect(Math.abs(anchors.points[key]!.y - y)).toBeLessThan(1e-6);
          }
          for (const fit of exp.fits) {
            const placement = fitAsset(
              asset,
              anchors,
              lm.image_width,
              lm.image_height,
              fit.adjustments,
            );
            for (let r = 0; r < 2; r += 1) {
              for (let col = 0; col < 3; col += 1) {
                expect(Math.abs(placement.matrix[r]![col]! - fit.matrix[r]![col]!)).toBeLessThan(
                  1e-9,
                );
              }
            }
            expect(placement.bbox).toEqual(fit.bbox);
          }
          expect(isStrand(asset)).toBe(exp.strands !== null);
          for (const strand of exp.strands ?? []) {
            const placement = strandPlacement(
              asset,
              anchors,
              lm.image_width,
              lm.image_height,
              strand.length_mm,
              strand.adjustments,
            );
            expect(placement.strips).toHaveLength(strand.strips.length);
            placement.strips!.forEach((strip, k) => {
              const want = strand.strips[k]!;
              expect(strip.x0).toBe(want.x0);
              expect(strip.x1).toBe(want.x1);
              for (let r = 0; r < 2; r += 1) {
                for (let col = 0; col < 3; col += 1) {
                  expect(Math.abs(strip.matrix[r]![col]! - want.matrix[r]![col]!)).toBeLessThan(1e-7);
                }
              }
            });
            expect(placement.bbox).toEqual(strand.bbox);
          }
        });
      });
    }
  }
});
